def implied_margin(p):
 lo,hi=.01,.5
 for _ in range(70):
  mid=(lo+hi)/2
  if d.calculate({'margin_target':mid})['EUR_per_share']<p:lo=mid
  else:hi=mid
 return (lo+hi)/2
