def table(df):
 data=[[para(c) for c in df.columns]]+[[para(round(v,3) if isinstance(v,(float,np.floating)) else v) for v in row] for row in df.itertuples(index=False,name=None)]
 t=Table(data,colWidths=[(doc.width)/len(df.columns)]*len(df.columns),repeatRows=1,hAlign='LEFT');t.setStyle(TableStyle([('BACKGROUND',(0,0),(-1,0),colors.HexColor('#dce9ed')),('VALIGN',(0,0),(-1,-1),'TOP'),('LINEBELOW',(0,0),(-1,0),.5,colors.grey),('BOTTOMPADDING',(0,0),(-1,-1),6)]));story.extend([t,Spacer(1,12)])
